#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void) {
    pid_t child = fork();
    if (child < 0) { perror("fork"); return 1; }
    if (child == 0) { puts("child finished"); fflush(stdout); _exit(0); }
    int status;
    if (waitpid(child, &status, 0) < 0) { perror("waitpid"); return 1; }
    puts("parent complete");
    return 0;
}

#include <stdio.h>
#include <sys/types.h>
#include <unistd.h>
int main(void) {
    pid_t child = fork();
    if (child < 0) { perror("fork"); return 1; }
    if (child == 0) { sleep(1); puts("child finished"); return 0; }
    puts("parent complete");
    return 0;
}

#include <stdio.h>
#include <sys/types.h>
#include <unistd.h>
int main(void) {
    pid_t pid = fork();
    if (pid < 0) { perror("fork"); return 1; }
    switch (pid) {
      case 0: sleep(1); puts("child finished"); return 0;
      default: puts("parent complete"); return 0;
    }
}

